WITH base AS (SELECT *, ROUND(quantity, 2) quantity_rounded FROM inventory WHERE last_restock >= TO_DATE('2023-03-09') AND store_id IN (1, 2, 4)), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id, store_id ORDER BY quantity DESC NULLS FIRST, id) AS row_num FROM base QUALIFY row_num = 1), latest AS (SELECT * FROM deduped QUALIFY ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY last_restock NULLS LAST, id) = 1), with_windows AS (SELECT *, NTILE(10) OVER (PARTITION BY store_id ORDER BY quantity_rounded, id) quantity_rounded_bucket, MIN(quantity_rounded) OVER (PARTITION BY store_id) store_id_min_quantity_rounded, PERCENT_RANK() OVER (PARTITION BY store_id ORDER BY quantity_rounded DESC NULLS LAST) quantity_rounded_percent_rank, NTILE(4) OVER (PARTITION BY product_id ORDER BY quantity_rounded, id) quantity_rounded_bucket_2, SUM(quantity) OVER (PARTITION BY product_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_quantity FROM latest) SELECT id, store_id, product_id, quantity, last_restock, quantity_rounded, row_num, quantity_rounded_bucket, store_id_min_quantity_rounded, quantity_rounded_percent_rank, quantity_rounded_bucket_2, cumulative_quantity, AVG(cumulative_quantity) OVER w_part cumulative_quantity_avg_3, NTILE(3) OVER (PARTITION BY store_id, product_id ORDER BY cumulative_quantity DESC, id) cumulative_quantity_bucket FROM with_windows WINDOW w_part AS (PARTITION BY store_id ORDER BY quantity_rounded_percent_rank, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)
